72		checkTwoItemSaved(t, list[0], "按点查询")
73		latest, ok, err := s.LatestResult("P1")
74		if err != nil || !ok || latest.ID != "S1" {
75			t.Fatalf("最近有效结果应指向 S1: %+v ok=%v err=%v", latest, ok, err)
76		}
