1	package water
2	
3	import (
4		"errors"
5		"reflect"
6		"testing"
7		"time"
8	)
9	
10	// 本文件的测试只针对一件事：已作废样品被同编号、同内容重复录入（重报）时，
11	// 只能把原作废记录作为“历史记录”幂等返回，不能借重报恢复它作为有效结果的
12	// 资格——状态不能变回待判定或已确认，作废前保存的逐项判定依据不能被当作
13	// 新结论重新参与最近有效结果。先确认后作废与从未确认就作废两种来路都覆盖：
14	// 前者的测量、逐项依据、整份超标标记与作废原因原样保留；后者本来就没有
15	// 逐项依据，重报也不能凭空判定，为假的超标标记不能解释成达标。
16	// 内容冲突沿用现有的 ErrSampleConflict 整体拒绝并返回空样品；拒绝不留痕，
17	// 之后提交合法原内容仍返回同一份作废记录。录入、查询、确认入口与错误含义
18	// 均保持现状。
19	
20	// checkVoidedS1 完整核对 S1 重报返回的就是作废时保存的那条历史记录：
21	// 状态必须仍是已作废并带原因；pH 9 > 8@09-01 超标、COD 30 == 30@09-01
22	// 达标、整份超标等作废前保存的内容逐字段保留；Measurements 与 Results
23	// 的项目排列必须仍是首次录入的 pH、COD 顺序，不能换成重报时的提交顺序。
24	func checkVoidedS1(t *testing.T, smp Sample, label string) {
25		t.Helper()
26		if smp.ID != "S1" || smp.PointID != "P1" || smp.Status != StatusVoided {
27			t.Fatalf("%s: 重报必须原样返作废记录，不能改变编号、采样点或作废状态: %+v", label, smp)
28		}
29		if smp.VoidReason != "采样瓶破损" {
30			t.Fatalf("%s: 作废原因应原样保留: %+v", label, smp)
31		}
32		if !smp.SampledAt.Equal(at(10, 0)) {
33			t.Fatalf("%s: 采样时间被改动: %+v", label, smp)
34		}
35		if !smp.Exceeded {
36			t.Fatalf("%s: 整份超标标记应保持作废前保存的 true: %+v", label, smp)
37		}
38		if len(smp.Measurements) != 2 || len(smp.Results) != 2 {
39			t.Fatalf("%s: 测量项目或历史判定依据数量被改动: %+v", label, smp)
40		}
41		wantOrder := []string{"pH", "COD"}
42		gotM := make([]string, len(smp.Measurements))
43		for i, m := range smp.Measurements {
44			gotM[i] = m.Item
45		}
46		if !reflect.DeepEqual(gotM, wantOrder) {
47			t.Fatalf("%s: 测量排列应保持首次录入的 pH、COD，不能换成重报顺序: %v",
48				label, gotM)
49		}
50		gotR := make([]string, len(smp.Results))
51		for i, r := range smp.Results {
52			gotR[i] = r.Item
53		}
54		if !reflect.DeepEqual(gotR, wantOrder) {
55			t.Fatalf("%s: 逐项结果排列应保持首次录入的 pH、COD: %v", label, gotR)
56		}
57		ms := map[string]float64{}
58		for _, m := range smp.Measurements {
59			ms[m.Item] = m.Value
60		}
61		if ms["pH"] != 9 || ms["COD"] != 30 {
62			t.Fatalf("%s: 原测量值被改动: %+v", label, smp.Measurements)
63		}
64		rs := map[string]ItemResult{}
65		for _, r := range smp.Results {
66			rs[r.Item] = r
67		}
68		ph, ok := rs["pH"]
69		if !ok || ph.Value != 9 || ph.Limit != 8.0 || !ph.LimitEffective.Equal(at(1, 0)) || !ph.Exceeded {
70			t.Fatalf("%s: pH 历史依据应为 9 > 8@09-01 超标: %+v", label, ph)
71		}
72		cod, ok := rs["COD"]
73		if !ok || cod.Value != 30 || cod.Limit != 30.0 || !cod.LimitEffective.Equal(at(1, 0)) || cod.Exceeded {
74			t.Fatalf("%s: COD 历史依据应为 30 == 30@09-01 达标: %+v", label, cod)
75		}
76	}
77	
78	// checkEarlierS0 完整核对最近有效结果退回的较早样品 S0：
79	// 返回内容必须整体属于 S0（pH 7、COD 20，两项与整份均达标），
80	// 不能混入作废记录 S1 的 pH 9、超标依据或任何字段。
81	func checkEarlierS0(t *testing.T, smp Sample, label string) {
82		t.Helper()
83		if smp.ID != "S0" || smp.PointID != "P1" || smp.Status != StatusConfirmed || smp.VoidReason != "" {
84			t.Fatalf("%s: 最近有效结果应整体属于较早的 S0: %+v", label, smp)
85		}
86		if !smp.SampledAt.Equal(at(5, 0)) {
87			t.Fatalf("%s: 采样时间不属于 S0: %+v", label, smp)
88		}
